import{_ as a,o as t,c as s,a0 as i}from"./chunks/framework.BLL-IG04.js";const h=JSON.parse('{"title":"Explanation: architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),o={name:"explanation/architecture.md"};function n(c,e,r,d,l,m){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="explanation-architecture" tabindex="-1">Explanation: architecture <a class="header-anchor" href="#explanation-architecture" aria-label="Permalink to &quot;Explanation: architecture&quot;">​</a></h1><p>mimus is the falsification half of the ecosystem: <em>&quot;every claim in your docs, comments, and memory — still true?&quot;</em> It exists because memory without doubt decays into confident confabulation.</p><h2 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The pipeline&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sources ──► extract ──► classify ──► verify ──► emit</span></span>
<span class="line"><span>   │          │           │           │          │</span></span>
<span class="line"><span> docs/*.md  claims     kinds:     checkers:   human |</span></span>
<span class="line"><span> comments   +lines     path…      fs cmd      json</span></span>
<span class="line"><span> .kuda/                 behavior  symbol      exit 1</span></span>
<span class="line"><span> cards                            rules</span></span></code></pre></div><p><strong>Extract</strong> pulls claim candidates (backticked spans, code blocks, prose patterns) with source+line.</p><p><strong>Classify</strong> sorts them into the taxonomy — conservatively: a span that might be a command but isn&#39;t in the binary allowlist is <em>not</em> a command claim.</p><p><strong>Verify</strong> runs the mechanical checkers plus <code>rules/*.toml</code>.</p><p><strong>Emit</strong> reports violations — or exits 1 to gate CI.</p><h2 id="ports-and-adapters" tabindex="-1">Ports and adapters <a class="header-anchor" href="#ports-and-adapters" aria-label="Permalink to &quot;Ports and adapters&quot;">​</a></h2><p><code>mimus-core</code> holds domain types only (<code>Claim</code>, <code>Violation</code>, <code>TrustScore</code>, config). Every concern is a trait crate + adapter crates:</p><ul><li><code>mimus-check</code> (the checker port) → <code>mimus-check-fs</code>, <code>mimus-check-cmd</code>, <code>mimus-check-symbol</code> (against kuda&#39;s index)</li><li>claim sources: markdown today, comments/cards wired in config</li><li><code>mimus-rules</code> — conventions as <code>rules/*.toml</code> data</li><li><code>mimus-vcs</code>→<code>mimus-git</code>, <code>mimus-config</code>→<code>mimus-config-toml</code>, <code>mimus-secret</code>→<code>mimus-keyring</code>/<code>mimus-dotenv</code></li></ul><p>A new checker = new adapter crate; a new convention = a new rule file.</p><h2 id="the-evidence-bar" tabindex="-1">The evidence bar <a class="header-anchor" href="#the-evidence-bar" aria-label="Permalink to &quot;The evidence bar&quot;">​</a></h2><p>A violation is claim + evidence + suggested fix. No evidence, no finding — false positives kill a critic faster than false negatives. The semantic tier can never gate CI: it reports, a human adjudicates. Style opinions are never emitted at all.</p><h2 id="position-in-the-ecosystem" tabindex="-1">Position in the ecosystem <a class="header-anchor" href="#position-in-the-ecosystem" aria-label="Permalink to &quot;Position in the ecosystem&quot;">​</a></h2><ul><li><code>kuda</code> builds the index; <code>mimus</code> doubts it — <code>audit</code> trust-scores cards against source via provenance hashes.</li><li><code>reconcile</code> (planned third tool) auto-fixes what mimus confirms: claims rewritten to match reality — it consumes the JSON violation contract, not the checkers.</li></ul><p>See <a href="./claims.html">claims &amp; tiers</a> for the taxonomy and why the two tiers can never merge.</p>`,17)])])}const u=a(o,[["render",n]]);export{h as __pageData,u as default};
